package com.example.utilmod.client;

import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;
import org.lwjgl.glfw.GLFW;

import java.util.ArrayList;
import java.util.List;

final class ModuleScreen extends Screen {

    private static final String[] CATEGORIES = {"Render", "Combat", "Movement", "Misc"};

        private static final int SIDEBAR_X = 8, SIDEBAR_Y = 8, SIDEBAR_W = 100;
            private static final int CAT_H = 22, CAT_GAP = 4;
                private static final int PANEL_X = 116, PANEL_Y = 8, PANEL_W = 250;
                    private static final int HEADER_H = 28, ROW_H = 18, SETTING_H = 16, MODULE_GAP = 6;

                        private static final int C_OVERLAY = 0x60000000;
                            private static final int C_SIDEBAR = 0xE0181820;
                                private static final int C_PANEL = 0xD0101014;
                                    private static final int C_ACCENT = 0xFF4FA3FF;
                                        private static final int C_ACCENT_DIM = 0x804FA3FF;
                                            private static final int C_TEXT = 0xFFEEEEEE;
                                                private static final int C_DIM = 0xFF9A9AA8;
                                                    private static final int C_ON = 0xFF5CE07A;
                                                        private static final int C_OFF = 0xFFE05C5C;
                                                            private static final int C_HOVER = 0x30FFFFFF;

                                                                private final List<Zone> zones = new ArrayList<>();
                                                                    private int selected = 0;

                                                                        ModuleScreen() {
                                                                                super(Component.literal("Utility Mod"));
                                                                                    }

                                                                                        @Override
                                                                                            public boolean isPauseScreen() {
                                                                                                    return false;
                                                                                                        }

                                                                                                            @Override
                                                                                                                public boolean keyPressed(int keyCode, int scanCode, int modifiers) {
                                                                                                                        if (keyCode == GLFW.GLFW_KEY_RIGHT_SHIFT) {
                                                                                                                                    onClose();
                                                                                                                                                return true;
                                                                                                                                                        }
                                                                                                                                                                return super.keyPressed(keyCode, scanCode, modifiers);
                                                                                                                                                                    }

                                                                                                                                                                        @Override
                                                                                                                                                                            public boolean mouseClicked(double mx, double my, int button) {
                                                                                                                                                                                    if (button == 0) {
                                                                                                                                                                                                for (Zone z : zones) {
                                                                                                                                                                                                                if (z.contains(mx, my)) {
                                                                                                                                                                                                                                    z.action().run();
                                                                                                                                                                                                                                                        return true;
                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                    return super.mouseClicked(mx, my, button);
                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                            @Override
                                                                                                                                                                                                                                                                                                                public void render(GuiGraphics g, int mx, int my, float partialTick) {
                                                                                                                                                                                                                                                                                                                        zones.clear();
                                                                                                                                                                                                                                                                                                                                g.fill(0, 0, width, height, C_OVERLAY);
                                                                                                                                                                                                                                                                                                                                        renderSidebar(g, mx, my);
                                                                                                                                                                                                                                                                                                                                                renderPanel(g, mx, my);
                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                        private void renderSidebar(GuiGraphics g, int mx, int my) {
                                                                                                                                                                                                                                                                                                                                                                int height = 28 + CATEGORIES.length * (CAT_H + CAT_GAP);
                                                                                                                                                                                                                                                                                                                                                                        g.fill(SIDEBAR_X, SIDEBAR_Y, SIDEBAR_X + SIDEBAR_W, SIDEBAR_Y + height, C_SIDEBAR);
                                                                                                                                                                                                                                                                                                                                                                                g.drawString(font, "UTILITY MOD", SIDEBAR_X + 8, SIDEBAR_Y + 9, C_ACCENT, false);

                                                                                                                                                                                                                                                                                                                                                                                        int y = SIDEBAR_Y + 28;
                                                                                                                                                                                                                                                                                                                                                                                                int x1 = SIDEBAR_X + 4;
                                                                                                                                                                                                                                                                                                                                                                                                        int x2 = SIDEBAR_X + SIDEBAR_W - 4;

                                                                                                                                                                                                                                                                                                                                                                                                                for (int i = 0; i < CATEGORIES.length; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                            boolean sel = i == selected;
                                                                                                                                                                                                                                                                                                                                                                                                                                        boolean hover = inside(mx, my, x1, y, x2 - x1, CAT_H);
                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (sel) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    g.fill(x1, y, x2, y + CAT_H, C_ACCENT_DIM);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    g.fill(x1, y, x1 + 2, y + CAT_H, C_ACCENT);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else if (hover) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                g.fill(x1, y, x2, y + CAT_H, C_HOVER);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        g.drawString(font, CATEGORIES[i], x1 + 10, y + 7,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            sel ? 0xFFFFFFFF : C_TEXT, false);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        final int idx = i;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    zones.add(new Zone(x1, y, x2 - x1, CAT_H, () -> selected = idx));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                y += CAT_H + CAT_GAP;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                private void renderPanel(GuiGraphics g, int mx, int my) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        String cat = CATEGORIES[selected];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                List<Feature> features = new ArrayList<>();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (Feature f : Features.ALL) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (f.category.equals(cat)) features.add(f);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int content = HEADER_H;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (Feature f : features) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        content += ROW_H + f.settings.size() * SETTING_H + MODULE_GAP;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int panelH = Math.max(content + 8, 60);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                g.fill(PANEL_X, PANEL_Y, PANEL_X + PANEL_W, PANEL_Y + panelH, C_PANEL);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        g.drawString(font, cat, PANEL_X + 10, PANEL_Y + 9, C_ACCENT, false);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int x1 = PANEL_X + 6;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int x2 = PANEL_X + PANEL_W - 6;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int y = PANEL_Y + HEADER_H;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (Feature f : features) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (inside(mx, my, x1, y, x2 - x1, ROW_H)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    g.fill(x1, y, x2, y + ROW_H, C_HOVER);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            g.drawString(font, f.name, x1 + 8, y + 5, C_TEXT, false);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        String state = f.enabled ? "ON" : "OFF";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    g.drawString(font, state, x2 - 8 - font.width(state), y + 5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        f.enabled ? C_ON : C_OFF, false);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    zones.add(new Zone(x1, y, x2 - x1, ROW_H, () -> f.enabled = !f.enabled));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                y += ROW_H;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (Setting s : f.settings) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            renderSetting(g, s, x1, y, x2, mx, my);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            y += SETTING_H;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    y += MODULE_GAP;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    private void renderSetting(GuiGraphics g, Setting s, int x1, int y, int x2, int mx, int my) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            g.drawString(font, s.name, x1 + 16, y + 4, C_DIM, false);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (s.isToggle) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                String v = s.display();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            g.drawString(font, v, x2 - 8 - font.width(v), y + 4, s.on ? C_ON : C_OFF, false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        zones.add(new Zone(x1 + 8, y, x2 - x1 - 8, SETTING_H, s::flip));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int minusX = x2 - 70;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int plusX = x2 - 18;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int by = y + 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int bw = 14;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int bh = SETTING_H - 2;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        drawButton(g, minusX, by, bw, bh, "-", mx, my);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    drawButton(g, plusX, by, bw, bh, "+", mx, my);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                String v = s.display();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            g.drawString(font, v, x2 - 40 - font.width(v) / 2, y + 4, C_TEXT, false);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        zones.add(new Zone(minusX, by, bw, bh, () -> s.adjust(-1)));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    zones.add(new Zone(plusX, by, bw, bh, () -> s.adjust(1)));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    private void drawButton(GuiGraphics g, int x, int y, int w, int h,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                String label, int mx, int my) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        boolean hover = inside(mx, my, x, y, w, h);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                g.fill(x, y, x + w, y + h, hover ? C_ACCENT_DIM : C_SIDEBAR);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        g.drawString(font, label, x + (w - font.width(label)) / 2, y + 3, C_TEXT, false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                private static boolean inside(int mx, int my, int x, int y, int w, int h) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return mx >= x && mx < x + w && my >= y && my < y + h;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                private record Zone(int x, int y, int w, int h, Runnable action) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        boolean contains(double mx, double my) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return mx >= x && mx < x + w && my >= y && my < y + h;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }